'use client'

import * as React from 'react'

// One player is rendered by `identity` and never by this file: the avatar
// cases, the signed-out case and the accessible name are decided there. This
// card owns the band, the eyebrow, the tail and the four card states, and
// nothing else.
import { Identity, type IdentityPlayer } from './identity'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled PlayerCard, and `tsc --noEmit` passes on it,
// so the gate cannot catch it.
import './player-card.css'
import { CrossGlyph, LockGlyph, StarGlyph, TickGlyph } from './glyphs'

/**
 * PlayerCard: one pickable player, as a card.
 *
 * The anatomy is fixed by specimen 3k and is what makes it a card rather than a
 * tile: a modifier band across the top, a portrait, an eyebrow, the player's
 * name, a meta line, and a tail. The band, the eyebrow and the tail are this
 * component's; the portrait, the name and the meta line are an `identity`,
 * rendered by `identity`. design/twins/3k.json measures each of those against
 * the drawing.
 *
 * It performs nothing. It does not decide whether a pick is allowed, does not
 * settle a result and does not know what a player is worth. The host owns the
 * card's state and hands it over; a press is reported and nothing more.
 *
 * Four states, which are the four the specimen draws: idle, selected,
 * committed, and settled. Selected is reversible and committed is not, and a
 * settled card carries `data-gs-state` with the result. Each changes the fill
 * or the stroke, a glyph and the accessible name together, never the colour on
 * its own.
 */

/** The three settled results, from the attribute contract's three-things rule. */
export type PlayerCardState = 'correct' | 'wrong' | 'rewarded'

export interface PlayerCardProps
  extends Omit<React.HTMLAttributes<HTMLElement>, 'children' | 'onSelect'> {
  /**
   * Who the card is for. `null` is the signed-out case, which `identity`
   * renders; a card for a slot nobody has filled is a real state a host shows.
   */
  player: IdentityPlayer | null
  /** The team the card stands for, when it stands for one. Rides `data-gs-team`. */
  team?: string
  /**
   * The band across the top: what picking this player is worth, in the host's
   * own words. "+1 Assist", "Captain", "Double points".
   */
  modifier?: React.ReactNode
  /**
   * The small line above the name: the drawing puts the player's first name
   * there, in capitals, over the surname. A string joins the accessible name.
   */
  eyebrow?: React.ReactNode
  /** The line under the name: club, number, position. Passed to `identity`. */
  meta?: React.ReactNode
  /** The tail under the card: the fixture, the kick-off, the odds. */
  detail?: React.ReactNode
  /** Picked, not yet committed. Reversible. */
  selected?: boolean
  /** Locked in. No longer reversible. */
  committed?: boolean
  /** How it settled, once the host knows. */
  state?: PlayerCardState
  /** Available later, not now. Keeps its shape and shows a padlock. */
  locked?: boolean
  /** Not available at all. */
  disabled?: boolean
  /** The name to announce, when the host has a better one than the player's. */
  label?: string
  /**
   * Makes the card the control that picks the player. Without it the card is a
   * rendering and the host's own button does the picking, which is what
   * specimen 3k draws.
   */
  onSelect?: (playerId: string | undefined) => void
}

/**
 * The words that go with the states. Taken from `choice`, because a card and an
 * option are the same four states and two vocabularies for them is how a
 * screen reader user ends up with two games.
 */
const STATE_WORD: Record<string, string> = {
  selected: 'selected',
  committed: 'locked in',
  correct: 'correct',
  wrong: 'wrong',
  rewarded: 'rewarded',
}


/**
 * The four marks a player card can show, from the shared set. They were four
 * inline paths here, on their own 16 grid at stroke 2.4, which is how the
 * library ended up with a tick in `player-card` that was a different drawing
 * from the tick in `segments` and the tick in `choice`.
 */
function Glyph({ state }: { state: PlayerCardState | 'locked' }) {
  if (state === 'correct') return <TickGlyph />
  if (state === 'wrong') return <CrossGlyph />
  if (state === 'rewarded') return <StarGlyph filled />
  return <LockGlyph />
}

export function PlayerCard({
  player,
  team,
  modifier,
  eyebrow,
  meta,
  detail,
  selected = false,
  committed = false,
  state,
  locked = false,
  disabled = false,
  label,
  onSelect,
  className,
  ...rest
}: PlayerCardProps) {
  // Committed wins over selected: a card the player locked in is not still
  // waiting to be picked, and two markers saying so would leave a host
  // deciding which one it believed.
  const picked = committed ? 'committed' : selected ? 'selected' : undefined
  const unavailable = disabled || locked

  // The name carries every state, because a screen reader user gets no fill, no
  // stroke and no glyph. Order: who it is, what picking them is worth, then
  // what is true of the card. A string eyebrow is the first name and goes in
  // front of the surname, as a person would say it.
  const who = player?.displayName ?? (player === null ? 'Guest' : 'Player')
  const words = [label ?? (typeof eyebrow === 'string' ? `${eyebrow} ${who}` : who)]
  if (typeof meta === 'string') words.push(meta)
  if (typeof modifier === 'string') words.push(modifier)
  if (picked) words.push(STATE_WORD[picked] as string)
  if (state) words.push(STATE_WORD[state] as string)

  // A settled card shows its result; a locked or committed card the padlock,
  // which is what the drawing puts in the committed band: locked in is locked.
  const glyph = state ?? (locked || committed ? 'locked' : undefined)

  const body = (
    <>
      {/* The band renders for a settled, committed or locked card even with no
          modifier, because the glyph is how the result reaches a player who
          cannot tell the two fills apart. */}
      {modifier === undefined && glyph === undefined ? null : (
        <span
          className="gs-player-card__band"
          data-gs-scope="player-card"
          data-gs-part="label"
          aria-hidden="true"
        >
          {glyph === undefined ? null : (
            // The glyph is emphasis: it appears with the state and does not
            // move, so a player on reduced motion still gets the answer.
            <span
              className="gs-player-card__glyph"
              data-gs-scope="player-card"
              data-gs-part="glyph"
              data-gs-animates="emphasis"
            >
              <Glyph state={glyph} />
            </span>
          )}
          {modifier}
        </span>
      )}
      {/* The portrait, the name and the meta line, all of them identity's. This
          file writes no avatar and no name of its own. The stylesheet lays the
          identity's pieces out as the card's own column, so the eyebrow below
          can sit between the portrait and the name. */}
      <Identity player={player} size="large" aria-hidden="true">
        {meta}
      </Identity>
      {eyebrow === undefined ? null : (
        <span className="gs-player-card__note" data-gs-scope="player-card" data-gs-part="note" aria-hidden="true">
          {eyebrow}
        </span>
      )}
      {detail === undefined ? null : (
        <span className="gs-player-card__tail" data-gs-scope="player-card" data-gs-part="detail" aria-hidden="true">
          {detail}
        </span>
      )}
    </>
  )

  const attributes = {
    className: ['gs-player-card', onSelect ? 'gs-pressable' : null, className]
      .filter(Boolean)
      .join(' '),
    'data-gs-component': 'player-card',
    'data-gs-player': player?.id,
    'data-gs-team': team,
    'data-gs-selected': picked === 'selected' ? ('true' as const) : undefined,
    'data-gs-committed': picked === 'committed' ? ('true' as const) : undefined,
    'data-gs-state': state,
    'data-gs-locked': locked ? ('true' as const) : undefined,
    'data-gs-disabled': disabled ? ('true' as const) : undefined,
    'aria-label': words.join(', '),
  }

  if (onSelect === undefined) {
    return (
      <div {...rest} {...attributes} role="group">
        {body}
      </div>
    )
  }

  return (
    <button
      {...rest}
      {...attributes}
      type="button"
      // The card moves on press, so it is motion and stops dead under reduced
      // motion. Its fill, stroke and glyph are emphasis and survive.
      data-gs-animates="motion"
      aria-pressed={picked !== undefined}
      aria-disabled={unavailable || undefined}
      disabled={disabled}
      onClick={() => {
        if (unavailable || committed) return
        onSelect(player?.id)
      }}
    >
      {body}
    </button>
  )
}

/* Player card. Every value comes from a token; nothing here is a literal colour.
 *
 * Specimen 3k draws this card twice, at 224px in the pick carousel and at 82px
 * in a strip of four states, and design/twins/3k.json measures ours against
 * both: the geometry and the type from the full-size card, the fills, strokes
 * and shelves of each state from the strip. Where a value below is not the
 * drawing's, the twins file names the nearest token and why.
 *
 * The press gesture comes from the shared rule set in
 * `app/gamestage-primitives.css`, which ships with `@gamestage/tokens`. Import
 * that file at your root beside the token stylesheet, or a pressable card will
 * not move.
 */

.gs-player-card {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  box-sizing: border-box;
  inline-size: 100%;
  /* Every card the same height, whatever it holds. Without this the card takes
     its height from its contents: a long fixture line, a two-line band or a
     missing detail each moved it, and eleven cards came out at five sizes. */
  block-size: 100%;
  margin: 0;
  /* The words at the bottom of the card sit 22px off its edge in the drawing,
     whichever line is last; space.6 is the nearest step. */
  padding: 0 0 var(--gs-space-6);
  overflow: hidden;
  text-align: center;

  background: var(--gs-color-surface);
  color: var(--gs-color-ink);
  border: var(--gs-stroke-control) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-xl);
  box-shadow: var(--gs-depth-raised);

  font-family: var(--gs-type-body-font-family);
  /* Emphasis: fill and stroke are the result, and a result a player only sees
     if they can see animation is not a result. */
  transition:
    background-color var(--gs-motion-emphasis) ease-out,
    border-color var(--gs-motion-emphasis) ease-out;
}

/* The card is a control only when the host gave it something to do, so the
   cursor and the focus ring follow the element rather than the class. */
button.gs-player-card {
  cursor: pointer;
}

/* The plain class selector, as `button`, `choice`, `reward` and `selector` all
   write it. A type-qualified `button.gs-player-card:focus-visible` did not take
   effect in the lab at all, and stage 8 caught it: the card rendered
   identically focused and unfocused, so a keyboard user could not see where
   focus was. */
.gs-player-card:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: var(--gs-space-1);
}

/* -- the column ------------------------------------------------------------ */
/* Band, portrait, eyebrow, name, meta, tail: one column, in that order.

   The portrait, the name and the meta line are an identity, which renders them
   as a picture beside a text block. The card needs them as rows of its own
   column, with its eyebrow between the picture and the name, so the identity's
   two wrappers are laid out as if they were not there and every row takes an
   `order`. The identity keeps its markup, its attributes and its name; only
   its boxes go. `.gs-identity__text` is the one wrapper with no part to select
   on, which is why a class of another component appears here. */
.gs-player-card [data-gs-component='identity'],
.gs-player-card [data-gs-component='identity'] > .gs-identity__text {
  display: contents;
}

/* -- the band -------------------------------------------------------------- */
/* What picking this player is worth. It is the top edge of the card, which is
   what specimen 3k uses to tell a card from a tile: 40 tall, the outline
   colour as its fill, the figure face in capitals.

   One line, always. It wrapped, and a wrapped band makes a taller card, so a
   row of cards came out at five different heights. Long copy is truncated with
   its full text still in the accessible name. */
.gs-player-card__band {
  order: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--gs-space-2);
  box-sizing: border-box;
  block-size: var(--gs-size-control-small);
  padding: 0 var(--gs-space-3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;

  background: var(--gs-color-edge);
  color: var(--gs-color-ink-secondary);

  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  /* The drawing tracks the band a little; the action axis's tracking is the
     library's one such token, borrowed. */
  letter-spacing: var(--gs-type-action-letter-spacing);
  text-transform: uppercase;
}

.gs-player-card__glyph {
  display: inline-flex;
  align-items: center;
  /* Emphasis, not motion: the glyph changes colour with the state and never
     moves, so it survives reduced motion. */
  transition: color var(--gs-motion-emphasis) ease-out;
}

/* -- the portrait ---------------------------------------------------------- */
/* Inset by the card's gutter on three sides, its own outline and the control
   radius, wider than it is tall. The drawing draws it 200 by 170 on the 224px
   card, and the ratio is that number: a portrait with a club mark beside it
   is a landscape slot. It used to run edge to edge at 4 by 5, which on a
   224px card put 280px of picture over 70px of words. */
/* Specificity beats identity's own size rules (`.gs-identity[data-gs-size]
   .gs-identity__avatar`), which set a square box on every step and, once they
   landed, made this portrait 200 tall instead of 170. */
.gs-player-card .gs-identity .gs-identity__avatar[data-gs-scope='identity'][data-gs-part='avatar'] {
  order: 1;
  box-sizing: border-box;
  /* Stretch across the card, then the ratio sets the height. With `auto` alone
     the slot took its width from the picture inside it once identity's image
     rule went to 100% both ways, and came out a 108px square. */
  align-self: stretch;
  inline-size: auto;
  block-size: auto;
  /* And no content floor: a flex item's automatic minimum is its content, and
     the picture inside (100% of an auto-height box resolves to the image's own
     height) held the slot at a square. The ratio is the height. */
  min-block-size: 0;
  aspect-ratio: 20 / 17;
  overflow: hidden;
  margin: var(--gs-space-3) var(--gs-space-3) 0;
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-control);
  object-fit: cover;
  /* The initials, when there is no picture, at the size the slot deserves. */
  font-size: var(--gs-type-stat-font-size);
}

/* -- the words ------------------------------------------------------------- */
/* The eyebrow: the first name in small capitals over the surname. */
.gs-player-card__note {
  order: 2;
  padding: var(--gs-space-3) var(--gs-space-3) 0;
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: var(--gs-type-label-letter-spacing);
  text-transform: uppercase;
  color: var(--gs-color-ink-secondary);
}

/* The name: the title face in capitals with the display shadow, as the
   drawing sets it. Identity sizes it; the card adds the case and the shadow. */
.gs-player-card [data-gs-scope='identity'][data-gs-part='label'] {
  order: 3;
  min-inline-size: 0;
  padding-inline: var(--gs-space-3);
  text-align: center;
  text-transform: uppercase;
  text-shadow: var(--gs-type-display-shadow);
  /* One line, like the band. Identity lets a name wrap anywhere, which is
     right in a row and wrong on a card: at the title size in capitals a
     seven-letter surname broke into HAALAN and D. Long names are cut with the
     full text still in the accessible name. */
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  overflow-wrap: normal;
}

/* Without an eyebrow the name is the first row under the portrait and takes
   the gutter itself. */
.gs-player-card:not(:has(.gs-player-card__note)) [data-gs-scope='identity'][data-gs-part='label'] {
  padding-top: var(--gs-space-3);
}

/* The meta line: club, number, position, and whatever mark the host puts
   before them, on one centred row in the label face. */
.gs-player-card [data-gs-scope='identity'][data-gs-part='detail'] {
  order: 4;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--gs-space-1);
  margin-top: var(--gs-space-2);
  padding-inline: var(--gs-space-3);
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  color: var(--gs-color-ink-secondary);
}

/* -- the tail -------------------------------------------------------------- */
/* The fixture, the kick-off: the caption face in the muted ink, the quietest
   line on the card. */
.gs-player-card__tail {
  order: 5;
  margin-top: var(--gs-space-1);
  padding-inline: var(--gs-space-3);
  font-family: var(--gs-type-caption-font-family);
  font-size: var(--gs-type-caption-font-size);
  font-weight: var(--gs-type-caption-font-weight);
  line-height: var(--gs-type-body-line-height);
  color: var(--gs-color-muted);
}

/* -- selected: reversible -------------------------------------------------- */
/* Stroke, band and ring together, never colour alone.

   The outline goes and the reward ring takes its place. The drawing declares
   a 3px outline in the reward colour, which in arcade is a gradient, so the
   browser drops the declaration and what it renders is a card with no outline
   inside a dark ring and a glow. depth.reward is that ring: a gap, then the
   reward colour, then the glow. Keeping an outline as well put a second yellow
   edge inside the ring and, measured, took 6px off the portrait. */
.gs-player-card[data-gs-selected='true'] {
  border: 0;
  box-shadow: var(--gs-depth-reward);
}

.gs-player-card[data-gs-selected='true'] .gs-player-card__band {
  background: var(--gs-color-reward);
  color: var(--gs-color-on-bright);
}

/* -- committed: not reversible --------------------------------------------- */
/* The interactive base as the outline, the interactive face on the band with
   the padlock in it, and no shelf: locked in is set down flat. */
.gs-player-card[data-gs-committed='true'] {
  border-color: var(--gs-color-interactive-base);
  border-width: var(--gs-stroke-selected);
  box-shadow: var(--gs-depth-flat);
}

.gs-player-card[data-gs-committed='true'] .gs-player-card__band {
  background: var(--gs-color-interactive);
  color: var(--gs-color-on-accent);
}

/* -- settled: fill or stroke, glyph, text ---------------------------------- */
/* A hit fills the whole card positive and turns the band dark, the reverse of
   every other state, which is what makes it read from across a room. */
.gs-player-card[data-gs-state='correct'] {
  background: var(--gs-color-positive);
  color: var(--gs-color-on-bright);
  border-color: var(--gs-color-edge);
}

.gs-player-card[data-gs-state='correct'] .gs-player-card__band {
  background: var(--gs-color-on-bright);
  color: var(--gs-color-ink);
}

/* A miss: the drawing's note says a dashed negative outline, the cross in the
   band, and the portrait drained of colour. */
.gs-player-card[data-gs-state='wrong'] {
  border-style: dashed;
  border-color: var(--gs-color-negative-solid);
}

.gs-player-card[data-gs-state='wrong'] .gs-player-card__band {
  color: var(--gs-color-negative-solid);
}

.gs-player-card[data-gs-state='wrong'] [data-gs-scope='identity'][data-gs-part='avatar'] {
  filter: grayscale(1);
}

.gs-player-card[data-gs-state='rewarded'] {
  border-color: var(--gs-color-reward-base);
  box-shadow: var(--gs-depth-reward);
}

.gs-player-card[data-gs-state='rewarded'] .gs-player-card__band {
  background: var(--gs-color-reward);
  color: var(--gs-color-on-bright);
}

/* -- locked and disabled --------------------------------------------------- */
/* Locked keeps its shape and shows a padlock. Only disabled goes flat. */
.gs-player-card[data-gs-locked='true'] {
  cursor: not-allowed;
}

.gs-player-card[data-gs-disabled='true'] {
  background: var(--gs-color-disabled);
  color: var(--gs-color-disabled-ink);
  box-shadow: var(--gs-depth-flat);
  cursor: not-allowed;
}
